<noscript><style>section.block{opacity:1;transform:none}</style></noscript>

<script>
(function(){
  "use strict";

  /* ---------- scroll progress + back-to-top ---------- */
  var bar = document.getElementById("progress");
  var toTop = document.getElementById("toTop");
  function onScroll(){
    var h = document.documentElement;
    var max = h.scrollHeight - h.clientHeight;
    bar.style.width = (max > 0 ? (h.scrollTop / max) * 100 : 0) + "%";
    toTop.classList.toggle("show", h.scrollTop > 600);
  }
  window.addEventListener("scroll", onScroll, {passive:true});
  onScroll();
  toTop.addEventListener("click", function(){
    window.scrollTo({top:0, behavior:"smooth"});
  });

  /* ---------- font size controls (persisted) ---------- */
  var fs = 16.5;
  try{
    var saved = parseFloat(localStorage.getItem("skyBilingualFs"));
    if(isFinite(saved) && saved >= 13 && saved <= 22) fs = saved;
  }catch(e){}
  function applyFs(){
    document.documentElement.style.setProperty("--content-fs", fs + "px");
    try{ localStorage.setItem("skyBilingualFs", String(fs)); }catch(e){}
  }
  document.getElementById("fontMinus").addEventListener("click", function(){
    fs = Math.max(13, fs - 1); applyFs();
  });
  document.getElementById("fontPlus").addEventListener("click", function(){
    fs = Math.min(22, fs + 1); applyFs();
  });
  applyFs();

  /* ---------- active nav highlight ---------- */
  var links = Array.prototype.slice.call(document.querySelectorAll(".topbar nav a"));
  var sections = Array.prototype.slice.call(document.querySelectorAll("section.block"));
  if("IntersectionObserver" in window){
    var navIO = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if(e.isIntersecting){
          links.forEach(function(l){
            l.classList.toggle("active", l.getAttribute("href") === "#" + e.target.id);
          });
        }
      });
    }, {rootMargin:"-35% 0px -55% 0px"});
    sections.forEach(function(s){ navIO.observe(s); });

    /* ---------- reveal on scroll ---------- */
    var revealIO = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if(e.isIntersecting){
          e.target.classList.add("in");
          revealIO.unobserve(e.target);
        }
      });
    }, {threshold:0.06});
    sections.forEach(function(s){ revealIO.observe(s); });
  }else{
    sections.forEach(function(s){ s.classList.add("in"); });
  }

  /* ---------- mirror highlight between language panels ---------- */
  Array.prototype.slice.call(document.querySelectorAll(".panels")).forEach(function(pair){
    var panels = pair.querySelectorAll(".panel");
    if(panels.length !== 2) return;
    var a = panels[0], b = panels[1];
    a.addEventListener("mouseenter", function(){ b.classList.add("match"); });
    a.addEventListener("mouseleave", function(){ b.classList.remove("match"); });
    b.addEventListener("mouseenter", function(){ a.classList.add("match"); });
    b.addEventListener("mouseleave", function(){ a.classList.remove("match"); });
  });
})();
</script>
</body>
</html>
"}

