from html.parser import HTMLParser

VOID = {'meta','br','hr','img','input','link','col','area','base','embed','source','track','wbr'}
class P(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag not in VOID:
            self.stack.append((tag, self.getpos()))
    def handle_endtag(self, tag):
        if tag in VOID: return
        if not self.stack:
            self.errors.append(f'extra </{tag}> at {self.getpos()}'); return
        if self.stack[-1][0] == tag:
            self.stack.pop()
        else:
            names = [t for t,_ in self.stack]
            if tag in names:
                while self.stack and self.stack[-1][0] != tag:
                    t, pos = self.stack.pop()
                    self.errors.append(f'unclosed <{t}> opened at {pos}')
                self.stack.pop()
            else:
                self.errors.append(f'stray </{tag}> at {self.getpos()}')

p = P()
p.feed(open('index.html', encoding='utf-8').read())
for t, pos in p.stack:
    p.errors.append(f'unclosed <{t}> opened at {pos}')
print('\n'.join(p.errors) if p.errors else 'OK: all tags balanced')
