    display:flex;align-items:center;justify-content:center;font-size:1rem;
  }
  .trivia .answer{
    max-height:0;overflow:hidden;opacity:0;
    transition:max-height .4s ease,opacity .4s ease,margin .4s ease;
    color:var(--muted);font-size:.94rem;margin:0;
  }
  .trivia.open .answer{max-height:14rem;opacity:1;margin-top:.6rem}
  .trivia .hint{font-size:.78rem;color:var(--muted);font-weight:600;margin-top:.3rem}

  /* ---------- footer & to-top ---------- */
  footer{
    max-width:1150px;margin:3rem auto 0;padding:1.5rem 1.25rem 2.5rem;
    border-top:1px solid var(--line);
    text-align:center;color:var(--muted);font-size:.87rem;
  }
  footer p{margin:.3rem 0}
  #toTop{
    position:fixed;left:1.25rem;bottom:1.25rem;z-index:55;
    width:2.6rem;height:2.6rem;border-radius:50%;
    border:1px solid var(--line);background:var(--card);color:var(--accent);
    font-size:1.15rem;font-weight:800;cursor:pointer;
    box-shadow:0 6px 18px rgba(0,0,0,.5);
    opacity:0;pointer-events:none;transform:translateY(8px);
    transition:opacity .25s ease,transform .25s ease;
  }
  #toTop.show{opacity:1;pointer-events:auto;transform:none}
  #toTop:hover{background:rgba(245,166,35,.15)}

  /* ---------- responsive ---------- */
  @media (max-width:920px){
    .explore-grid,.mag-grid,.journey-grid{grid-template-columns:1fr}
    .layer-grid,.crust-grid,.trivia-grid{grid-template-columns:1fr}
    .stats{grid-template-columns:repeat(2,1fr)}
    .topbar nav{margin-inline-start:0;width:100%}
  }
  @media (prefers-reduced-motion:reduce){
    html{scroll-behavior:auto}
    .reveal{opacity:1;transform:none;transition:none}
    *{animation:none!important;transition:none!important}
  }
</style>
</head>
<body>

<div class="stars" aria-hidden="true"></div>
<div id="progress" aria-hidden="true"></div>

<!-- SVG definitions & shared Earth cross-section -->
<svg width="0" height="0" style="position:absolute" aria-hidden="true">
  <defs>
    <radialGradient id="mantleGrad" cx="50%" cy="50%" r="65%">
      <stop offset="0%" stop-color="#e8834a"/>
      <stop offset="70%" stop-color="#d96f2b"/>
      <stop offset="100%" stop-color="#c25a1c"/>
    </radialGradient>
    <radialGradient id="outerGrad" cx="50%" cy="50%" r="60%">
      <stop offset="0%" stop-color="#ffd35c"/>
      <stop offset="100%" stop-color="#f5a623"/>
    </radialGradient>
    <radialGradient id="innerGrad" cx="50%" cy="50%" r="60%">
