      <stop offset="100%" stop-color="#ffd76e"/>
    </radialGradient>
    <radialGradient id="glowGrad" cx="50%" cy="50%" r="50%">
      <stop offset="0%" stop-color="rgba(255,223,138,.55)"/>
      <stop offset="100%" stop-color="rgba(255,223,138,0)"/>
