  </defs>
  <symbol id="earthCore" viewBox="0 0 460 400">
    <circle cx="230" cy="200" r="197" fill="none" stroke="rgba(159,176,201,.25)" stroke-width="1"/>
    <circle cx="230" cy="200" r="190" fill="#8d6e63"/>
    <circle cx="230" cy="200" r="183" fill="url(#mantleGrad)"/>
    <circle class="glow" cx="230" cy="200" r="72" fill="url(#glowGrad)"/>
    <circle cx="230" cy="200" r="103.4" fill="url(#outerGrad)"/>
    <circle cx="230" cy="200" r="36.4" fill="url(#innerGrad)"/>
    <circle cx="230" cy="200" r="190" fill="none" stroke="rgba(0,0,0,.35)" stroke-width="1.5"/>
    <circle cx="230" cy="200" r="183" fill="none" stroke="rgba(0,0,0,.25)" stroke-width="1"/>
    <circle cx="230" cy="200" r="103.4" fill="none" stroke="rgba(0,0,0,.3)" stroke-width="1"/>
  </symbol>
</svg>

<header class="topbar">
  <div class="brand">🌍 طبقات الأرض</div>
  <nav aria-label="الأقسام">
    <a href="#explore">الاستكشاف</a>
    <a href="#layers">الطبقات</a>
    <a href="#crust">القشرة</a>
    <a href="#magnetism">المغناطيسية</a>
    <a href="#journey">رحلة العمق</a>
    <a href="#compare">مقارنة</a>
  </nav>
</header>

<main>

  <!-- ================= HERO ================= -->
  <div class="hero" id="top">
    <span class="kicker">رحلة إلى قلب الكوكب · ٦٣٧١ كم</span>
    <h1>طبقات <span class="hl">الأرض</span> الجيولوجية</h1>
    <p class="sub">
      من قشرة رقيقة نمشي فوقها، إلى وِشاح متوهّج، ثم نواة من حديد منصهر قلبها صلب كالحجر:
      الأرض ثلاثةُ أقسام رئيسية (القشرة، الوشاح، النواة) تنطوي بداخلها أسرار ضغطٍ وحرارةٍ ومغناطيسية.
      استكشفها هنا بالرسوم التفاعلية.
    </p>
    <div class="ctas">
      <a class="btn primary" href="#explore">🔍 استكشف المقطع الداخلي</a>
      <a class="btn" href="#journey">⬇️ ابدأ رحلة العمق</a>
    </div>
    <svg class="earth-hero" viewBox="0 0 460 400" role="img" aria-label="مقطع عرضي للأرض يوضح طبقاتها">
      <use href="#earthCore"/>
    </svg>
    <p class="note">سماكة القشرة مبالغ فيها في الرسم للوضوح. الأبعاد الأخرى تقريبية.</p>
  </div>

  <!-- ================= EXPLORER ================= -->
  <section id="explore" class="reveal">
    <div class="sec-head">
      <span class="kicker">١ · تفاعلي</span>
      <h2>استكشف المقطع الداخلي</h2>
      <p>مرّر المؤشر فوق الطبقات أو انقر عليها (أو استخدم الأزرار) لعرض بيانات كل طبقة: عمقها، حرارتها، تركيبها، وحالتها.</p>
    </div>
    <div class="explore-grid">
      <div class="card diagram">
        <svg viewBox="0 0 460 400" role="img" aria-label="مقطع تفاعلي لطبقات الأرض">
          <use href="#earthCore"/>
          <!-- hit areas (innermost drawn last = on top) -->
          <circle class="l-hit" data-layer="crust" cx="230" cy="200" r="190" pointer-events="all"/>
          <circle class="l-hit" data-layer="mantle" cx="230" cy="200" r="183" pointer-events="all"/>
          <circle class="l-hit" data-layer="outerCore" cx="230" cy="200" r="103.4" pointer-events="all"/>
          <circle class="l-hit" data-layer="innerCore" cx="230" cy="200" r="36.4" pointer-events="all"/>
          <circle id="activeRing" cx="230" cy="200" r="190" pointer-events="none"/>
          <!-- labels -->
          <g font-size="15" fill="#e8eef8">
            <line x1="96" y1="66" x2="75" y2="48" stroke="#9fb0c9" stroke-width="1"/>
            <text x="70" y="42" text-anchor="end" font-weight="700">القشرة</text>
            <line x1="331" y1="99" x2="382" y2="60" stroke="#9fb0c9" stroke-width="1"/>
            <text x="387" y="58" text-anchor="start" font-weight="700">الوشاح</text>
            <line x1="178" y1="251" x2="88" y2="300" stroke="#9fb0c9" stroke-width="1"/>
            <text x="30" y="318" text-anchor="start" font-weight="700">النواة الخارجية</text>
            <text x="30" y="338" text-anchor="start" font-size="12" fill="#9fb0c9">٢٩٠٠ – ٥١٥٠ كم</text>
            <line x1="230" y1="237" x2="230" y2="330" stroke="#9fb0c9" stroke-width="1" stroke-dasharray="3 4"/>
            <text x="230" y="352" text-anchor="middle" font-weight="700">النواة الداخلية</text>
            <line x1="420" y1="146" x2="413" y2="191" stroke="#9fb0c9" stroke-width="1"/>
            <text x="432" y="142" text-anchor="middle" font-size="12" fill="#9fb0c9">السطح</text>
          </g>
        </svg>
      </div>
      <div class="card info" id="infoPanel" aria-live="polite">
        <div class="chips" role="group" aria-label="اختيار الطبقة">
          <button class="chipbtn active" data-layer="crust" type="button">القشرة</button>
          <button class="chipbtn" data-layer="mantle" type="button">الوشاح</button>
          <button class="chipbtn" data-layer="outerCore" type="button">النواة الخارجية</button>
          <button class="chipbtn" data-layer="innerCore" type="button">النواة الداخلية</button>
        </div>
        <h3><span class="dot" id="infoDot"></span><span id="infoTitle">القشرة الأرضية</span><span class="en" id="infoEn">Crust</span></h3>
        <dl>
          <div class="row"><dt>العمق</dt><dd id="infoDepth"></dd></div>
          <div class="row"><dt>درجة الحرارة</dt><dd id="infoTemp"></dd></div>
          <div class="row"><dt>التركيب</dt><dd id="infoComp"></dd></div>
          <div class="row"><dt>الحالة</dt><dd id="infoState"></dd></div>
        </dl>
        <p class="fact" id="infoFact"></p>
      </div>
    </div>
  </section>

  <!-- ================= LAYER CARDS ================= -->
  <section id="layers" class="reveal">
    <div class="sec-head">
      <span class="kicker">٢ · بالتفصيل</span>
      <h2>الطبقات الأربع</h2>
      <p>ثلاث طبقات رئيسية، تتفرع النواة منها إلى قسمين خارجي سائل وداخلي صلب — إجمالًا أربع طبقات نعرفها بالزلزالات.</p>
    </div>
    <div class="layer-grid">

      <article class="card lcard reveal" style="--lc:var(--crust)">
        <h3><span class="dot"></span>القشرة الأرضية <span class="en">Crust</span></h3>
        <div class="meta">
          <span>العمق: <b>٠ – ٧٠ كم</b></span>
          <span>الحرارة: <b>١٥ – ٨٠٠°م</b></span>
          <span>الحالة: <b>صلبة</b></span>
        </div>
        <p>الطبقة الصخرية الرقيقة التي نعيش على سطحها. <b>القارية</b> أسمك (٣٠–٧٠ كم) وبنيتُها غرانيتية، و<b>المحيطية</b> أرق (٥–١٠ كم) وبازلتية، وتُفصلها عن الوشاح <b>حدود مورافيتش</b>.</p>
        <p>تندمج القشرة مع الجزء العلوي من الوشاح لتكوّن <b>الغلاف الصخري</b>، وهو الذي يتفتّت إلى صفائح تكتونية تنزلق فوق الطبقة الهشّة — مصدر الزلازل والبراكين على حدودها.</p>
      </article>

      <article class="card lcard reveal" style="--lc:var(--mantle)">
        <h3><span class="dot"></span>الوشاح <span class="en">Mantle</span></h3>
        <div class="meta">
          <span>العمق: <b>٧٠ – ٢٩٠٠ كم</b></span>
          <span>الحرارة: <b>٥٠٠ – ٣٧٠٠°م</b></span>
          <span>الحالة: <b>صلبة متدفقة</b></span>
        </div>
        <p>أكبر الطبقات حجمًا: نحو <b>٨٢٪ من حجم الأرض</b>. مكوّن من سيليكاتات كثيفة غنية بالحديد والمغنيسيوم (أوليفين وبيروكسين).</p>
        <p>يتكوّن من: الوشاح العلوي (وفي قلبه <b>الطبقة الهشّة</b> ١٠٠–٢٥٠ كم حيث تحدث الانصهارات الجزئية)، <b>منطقة الانتقال</b> (٤١٠–٦٦٠ كم)، والوشاح السفلي (٦٦٠–٢٩٠٠ كم). صلبٌ لكنه يتسلّل ببطء في خلايا حمل حراري على مدى ملايين السنين — وهذه الحركة هي <b>محرّك الصفائح التكتونية</b>.</p>
      </article>

      <article class="card lcard reveal" style="--lc:var(--outer)">
        <h3><span class="dot"></span>النواة الخارجية <span class="en">Outer core</span></h3>
        <div class="meta">
          <span>العمق: <b>٢٩٠٠ – ٥١٥٠ كم</b></span>
          <span>الحرارة: <b>٤٠٠٠ – ٥٠٠٠°م</b></span>
          <span>الحالة: <b>سائلة</b></span>
        </div>
        <p>طبقة من <b>الحديد والنيكل المنصهرين</b> مع عناصر أخف (أكسجين، كبريت، سيليكون). لا تعبرها الموجات الزلزالية الثانوية (S) — وهو الدليل القاطع على سائليتها.</p>
        <p>حركتها الدوّارة تولّد ظاهرة <b>الدينامو الجيولوجي</b> التي تصنع المجال المغناطيسي للأرض، الدرع التي تحمي غلافنا الجوي والحياة من الرياح الشمسية.</p>
      </article>

      <article class="card lcard reveal" style="--lc:var(--inner)">
        <h3><span class="dot"></span>النواة الداخلية <span class="en">Inner core</span></h3>
        <div class="meta">
          <span>العمق: <b>٥١٥٠ – ٦٣٧١ كم</b></span>
          <span>الحرارة: <b>≈ ٥٤٠٠°م</b></span>
          <span>الحالة: <b>صلبة</b></span>
        </div>
        <p>رغم حرارة تقارب <b>حرارة سطح الشمس</b>، تبقى صلبة لأن الضغط الهائل (≈ ٣٦٠ غيغاباسكال، أي نحو ٣٫٦ مليون ضعف الضغط الجوي) يحبس الذرات في مكانها.</p>
        <p>نصف قطرها ≈ <b>١٢٢١ كم</b> — بحجم كوكب المريخ تقريبًا. اكتشفتها عالمة الزلازل <b>إنغه ليمان</b> عام ١٩٣٦ من أنماط الموجات الزلزالية، دون أي حفر.</p>
      </article>

    </div>
  </section>

  <!-- ================= CRUST TYPES ================= -->
  <section id="crust" class="reveal">
    <div class="sec-head">
      <span class="kicker">٣ · نوعان مختلفان</span>
      <h2>وجهان للقشرة: قارية ومحيطية</h2>
      <p>القشرة ليست طبقة موحّدة؛ فهي نوعان يختلفان سماكةً ووزنًا وعمرًا.</p>
    </div>
    <div class="crust-grid">

      <article class="card reveal">
        <h3>🌊 القشرة المحيطية</h3>
        <svg viewBox="0 0 300 170" role="img" aria-label="مقطع مبسّط للقشرة المحيطية تحت المحيط">
          <rect x="0" y="0" width="300" height="45" fill="#1b4f8a"/>
          <path d="M0 12 Q 25 6 50 12 T 100 12 T 150 12 T 200 12 T 250 12 T 300 12" fill="none" stroke="#7db8e8" stroke-width="2"/>
          <rect x="0" y="45" width="300" height="26" fill="#5d4037"/>
          <rect x="0" y="71" width="300" height="99" fill="url(#mantleGrad)"/>
          <text x="14" y="30" fill="#dceaff" font-size="13" font-weight="700">المحيط</text>
          <text x="14" y="63" fill="#f3e5d8" font-size="12" font-weight="700">قشرة بازلتية (٥–١٠ كم)</text>
          <text x="14" y="140" fill="#ffe0c2" font-size="12" font-weight="700">الوشاح</text>
        </svg>
        <ul>
          <li><b>رقيقة وكثيفة:</b> ٥–١٠ كم، بنيتُها بازلتية داكنة.</li>
          <li><b>الشابة دائمًا:</b> تتجدّد عند حدود الصفائح، وأكثرها أحدث من ٢٠٠ مليون سنة.</li>
          <li>تنزلق وتغوص (<b>التقمص</b>) تحت الصفائح القارية عند الخنادق البحرية.</li>
        </ul>
      </article>

      <article class="card reveal">
        <h3>⛰️ القشرة القارية</h3>
        <svg viewBox="0 0 300 170" role="img" aria-label="مقطع مبسّط للقشرة القارية مع الجبال">
          <rect x="0" y="0" width="300" height="170" fill="url(#mantleGrad)"/>
          <polygon points="0,45 40,18 85,45 130,25 175,45 225,15 265,42 300,38 300,75 0,75" fill="#8d6e63"/>
          <rect x="0" y="75" width="300" height="0" fill="none"/>
          <text x="14" y="14" fill="#ffe0c2" font-size="12" font-weight="700">جو</text>
          <text x="195" y="66" fill="#f3e5d8" font-size="12" font-weight="700">قشرة غرانيتية (٣٠–٧٠ كم)</text>
          <text x="14" y="140" fill="#ffe0c2" font-size="12" font-weight="700">الوشاح</text>
        </svg>
        <ul>
          <li><b>أسمك وأخف:</b> ٣٠–٧٠ كم، بنيتُها غرانيتية غنية بالسيليكا.</li>
          <li><b>العملاقة في العمر:</b> أقسامها قد يتجاوز عمرها ٤ مليارات سنة.</li>
          <li>تطفو فوق القشرة المحيطية لكونها أخف كثافة — ولهذا ترتفع القارات فوق مستوى البحار.</li>
        </ul>
      </article>

    </div>
  </section>

  <!-- ================= MAGNETISM ================= -->
  <section id="magnetism" class="reveal">
    <div class="sec-head">
      <span class="kicker">٤ · القلب المولّد</span>
      <h2>لماذا الأرضُ مغناطيسٌ ضخم؟</h2>
      <p>حركة الحديد المنصهر في النواة الخارجية — ظاهرة الدينامو — تولّد المجال المغناطيسي الذي يمتد آلاف الكيلومترات في الفضاء.</p>
    </div>
    <div class="mag-grid">
      <div class="card">
        <svg viewBox="0 0 520 400" role="img" aria-label="مخطط المجال المغناطيسي للأرض مع الغلاف المغناطيسي والرياح الشمسية">
          <defs>
            <marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse">
              <path d="M0,0 L10,5 L0,10 z" fill="#f5a623"/>
            </marker>
          </defs>
          <!-- magnetosphere shield -->
          <ellipse cx="260" cy="200" rx="235" ry="175" fill="none" stroke="rgba(125,184,232,.5)" stroke-width="1.5" stroke-dasharray="6 8"/>
          <text x="260" y="22" text-anchor="middle" fill="#7db8e8" font-size="13" font-weight="700">الغلاف المغناطيسي</text>
          <!-- solar wind particles -->
          <g fill="#9ec5ff">
            <circle cx="60" cy="60" r="3"/><circle cx="105" cy="42" r="2.4"/><circle cx="42" cy="110" r="2.6"/>
          </g>
          <line x1="70" y1="68" x2="92" y2="88" stroke="#9ec5ff" stroke-width="1.5" marker-end="url(#arrow)"/>
          <line x1="115" y1="50" x2="133" y2="66" stroke="#9ec5ff" stroke-width="1.5" marker-end="url(#arrow)"/>
          <text x="40" y="140" fill="#9ec5ff" font-size="12" font-weight="700">الرياح الشمسية</text>
          <!-- field lines (left) -->
          <g fill="none" stroke="#f5a623" stroke-width="2">
            <path class="fline" d="M 238,138 C 190,112 172,288 238,262" marker-end="url(#arrow)"/>
            <path class="fline" d="M 230,128 C 152,84 128,316 230,272" marker-end="url(#arrow)"/>
            <path class="fline" d="M 222,118 C 96,58 72,342 222,282" marker-end="url(#arrow)"/>
          </g>
          <!-- field lines (right) -->
          <g fill="none" stroke="#f5a623" stroke-width="2">
            <path class="fline" d="M 282,138 C 330,112 348,288 282,262" marker-end="url(#arrow)"/>
            <path class="fline" d="M 290,128 C 368,84 392,316 290,272" marker-end="url(#arrow)"/>
            <path class="fline" d="M 298,118 C 424,58 448,342 298,282" marker-end="url(#arrow)"/>
          </g>
          <!-- earth -->
          <circle cx="260" cy="200" r="80" fill="url(#mantleGrad)"/>
          <circle cx="260" cy="200" r="52" fill="url(#outerGrad)"/>
          <circle cx="260" cy="200" r="18" fill="url(#innerGrad)"/>
          <circle cx="260" cy="200" r="80" fill="none" stroke="rgba(0,0,0,.35)" stroke-width="1.5"/>
          <!-- convection arrows in outer core -->
          <path d="M 238,222 A 30 30 0 0 1 262,176" fill="none" stroke="#7a4c00" stroke-width="2.5" marker-end="url(#arrow)"/>
          <path d="M 282,178 A 30 30 0 0 1 258,224" fill="none" stroke="#7a4c00" stroke-width="2.5" marker-end="url(#arrow)"/>
          <!-- poles -->
          <text x="260" y="112" text-anchor="middle" fill="#ffe9ad" font-size="12" font-weight="700">الشمال المغناطيسي</text>
          <text x="260" y="302" text-anchor="middle" fill="#ffe9ad" font-size="12" font-weight="700">الجنوب المغناطيسي</text>
          <text x="260" y="205" text-anchor="middle" fill="#3a2400" font-size="11" font-weight="700">دينامو</text>
        </svg>
      </div>
