<script>
(function(){
  "use strict";

  /* ---------- helpers ---------- */
  function arNum(n){ return String(n).replace(/\d/g, function(d){ return "٠١٢٣٤٥٦٧٨٩"[d]; }); }
  function fmtArabic(n){
    var s = Number(n).toLocaleString("en-US");           // 2,900
    return arNum(s).replace(/,/g, "٬");                  // ٢٬٩٠٠
  }
  function fmtTemp(n){
    var t = Math.round(n / 10) * 10;
    return fmtArabic(t) + "°م";
  }

  /* ---------- scroll progress + back-to-top ---------- */
  var bar = document.getElementById("progress");
  var toTop = document.getElementById("toTop");
  function onScroll(){
    var h = document.documentElement;
    var max = h.scrollHeight - h.clientHeight;
    bar.style.width = (max > 0 ? (h.scrollTop / max) * 100 : 0) + "%";
    toTop.classList.toggle("show", h.scrollTop > 600);
  }
  window.addEventListener("scroll", onScroll, {passive:true});
  onScroll();
  toTop.addEventListener("click", function(){ window.scrollTo({top:0, behavior:"smooth"}); });

  /* ---------- layer data ---------- */
  var LAYERS = {
    crust: {
      title:"القشرة الأرضية", en:"Crust", color:"var(--crust)", ringR:190,
      depth:"٠ – ٧٠ كم (متوسط ≈ ٣٥ كم)",
      temp:"١٥°م حتى ≈ ٨٠٠°م عند القاعدة",
      comp:"صخور سيليكاتية: غرانيت في القارية، وبازلت في المحيطية",
      state:"صلبة، متصدعة إلى صفائح تكتونية",
      fact:"💡 أنحف الطبقات: لو كانت الأرض تفاحة، لكانت القشرة أرقّ من قشرتها."
    },
    mantle: {
      title:"الوشاح", en:"Mantle", color:"var(--mantle)", ringR:183,
      depth:"≈ ٧٠ – ٢٩٠٠ كم",
      temp:"≈ ٥٠٠°م حتى ≈ ٣٧٠٠°م",
      comp:"سيليكاتات كثيفة غنية بالحديد والمغنيسيوم (أوليفين، بيروكسين)",
      state:"صلبة تتسلّل ببطء (حمل حراري)",
      fact:"💡 يشكّل نحو ٨٢٪ من حجم الأرض، وحرارته البطيئة هي محرّك الصفائح التكتونية."
    },
    outerCore: {
      title:"النواة الخارجية", en:"Outer core", color:"var(--outer)", ringR:103.4,
      depth:"٢٩٠٠ – ٥١٥٠ كم",
      temp:"٤٠٠٠ – ٥٠٠٠°م",
      comp:"حديد ونيكل منصهران مع عناصر أخف (أكسجين، كبريت، سيليكون)",
      state:"سائلة",
      fact:"💡 دورانها المنصهر يولّد الدينامو الذي يصنع المجال المغناطيسي الواقي."
    },
    innerCore: {
      title:"النواة الداخلية", en:"Inner core", color:"var(--inner)", ringR:36.4,
      depth:"٥١٥٠ – ٦٣٧١ كم",
      temp:"≈ ٥٤٠٠°م (تقارب حرارة سطح الشمس)",
      comp:"سبيكة حديد ونيكل صلبة",
      state:"صلبة (بسبب ضغط ≈ ٣٦٠ غيغاباسكال)",
      fact:"💡 نصف قطرها ≈ ١٢٢١ كم — بحجم كوكب المريخ تقريبًا."
    }
  };

  /* ---------- explorer ---------- */
  var info = {
    dot: document.getElementById("infoDot"),
    title: document.getElementById("infoTitle"),
    en: document.getElementById("infoEn"),
    depth: document.getElementById("infoDepth"),
    temp: document.getElementById("infoTemp"),
    comp: document.getElementById("infoComp"),
    state: document.getElementById("infoState"),
    fact: document.getElementById("infoFact"),
    panel: document.getElementById("infoPanel")
  };
  var ring = document.getElementById("activeRing");
  var chips = Array.prototype.slice.call(document.querySelectorAll(".chipbtn[data-layer]"));
  var hits = Array.prototype.slice.call(document.querySelectorAll(".l-hit"));

  function selectLayer(key){
    var L = LAYERS[key];
    if(!L) return;
    info.dot.style.background = L.color;
    info.title.textContent = L.title;
    info.en.textContent = L.en;
    info.depth.textContent = L.depth;
    info.temp.textContent = L.temp;
    info.comp.textContent = L.comp;
    info.state.textContent = L.state;
    info.fact.textContent = L.fact;
    ring.setAttribute("r", L.ringR);
    chips.forEach(function(c){ c.classList.toggle("active", c.dataset.layer === key); });
    info.panel.classList.remove("pop");
    void info.panel.offsetWidth;
    info.panel.classList.add("pop");
  }
  chips.forEach(function(c){ c.addEventListener("click", function(){ selectLayer(c.dataset.layer); }); });
  hits.forEach(function(h){ h.addEventListener("click", function(){ selectLayer(h.dataset.layer); }); });
  selectLayer("crust");

  /* ---------- journey ---------- */
  var slider = document.getElementById("jSlider");
  var jDepth = document.getElementById("jDepth");
  var jTemp = document.getElementById("jTemp");
  var jState = document.getElementById("jState");
  var jPct = document.getElementById("jPct");
  var jBadge = document.getElementById("jBadge");
  var jMarker = document.getElementById("jMarker");
  var jLine = document.getElementById("jLine");
  var JCX = 110, JCY = 118, JR = 100;

  function layerAt(d){
    if(d < 35) return "crust";
    if(d < 2900) return "mantle";
    if(d <= 5150) return "outerCore";
    return "innerCore";
  }
  function tempAt(d){
    if(d <= 35) return 15 + (800 - 15) * (d / 35);
    if(d < 2900) return 800 + (3700 - 800) * ((d - 35) / (2900 - 35));
    if(d <= 5150) return 4000 + (5000 - 4000) * ((d - 2900) / (5150 - 2900));
    return 5000 + (5500 - 5000) * ((d - 5150) / (6371 - 5150));
  }
  function updateJourney(d){
    d = Math.max(0, Math.min(6371, +d));
    var key = layerAt(d);
    var L = LAYERS[key];
    jDepth.textContent = fmtArabic(d) + " كم";
    jTemp.textContent = fmtTemp(tempAt(d));
    jState.textContent = (key === "outerCore") ? "سائلة 🌊" : "صلبة 🪨";
    jPct.textContent = arNum((d / 6371 * 100).toFixed(1)) + "٪";
    jBadge.textContent = L.title;
    jBadge.className = "badge b-" + key;
    var r = JR * (1 - d / 6371);
    var y = JCY + r;
