    LaunchedEffect(Unit) {
        while (true) {
            val diffMs = System.currentTimeMillis() - BuildConfig.BUILD_TIME
            val diffMin = diffMs / (1000 * 60)
            buildTimeText = if (diffMin < 1) "Built: just now" else "Built: $diffMin min ago"
            delay(60000)
        }
    }

    Surface(
        color = Color.Black.copy(alpha = 0.5f),
        shape = CircleShape
    ) {
        Text(
            text = buildTimeText,
            modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp),
            color = Color.White,
            style = MaterialTheme.typography.labelMedium
        )
    }
}

fun Context.findActivity(): ComponentActivity? = when (this) {
    is ComponentActivity -> this
    is ContextWrapper -> baseContext.findActivity()
    else -> null
}

fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "N/A"
    val seconds = exposureTimeNs / 1_000_000_000.0
    return when {
        seconds < 0.5 -> "1/${(1.0 / seconds).roundToInt()}s"
        seconds < 1.0 -> {
            val s = String.format(Locale.US, "%.3f", seconds)
            s.trimEnd('0').trimEnd('.') + "s"
        }
        seconds % 1.0 == 0.0 -> "${seconds.toLong()}s"
        else -> String.format(Locale.US, "%.1f", seconds) + "s"
    }
}
